STYLE FIGMA                      CSS VARIABLE
Warna/Latar      #FFFBF5         --color-latar: #FFFBF5;
Warna/Teks       #2B1D14         --color-teks: #2B1D14;
Warna/Aksen      #B45309         --color-aksen: #B45309;
Warna/Aksen Gelap #92400E        --color-aksen-gelap: #92400E;
Teks/Judul H1    700 40/48       --type-judul-h1: 700 2.5rem/1.2 "Fraunces", system-ui, sans-serif;
Teks/Isi         400 16/26       --type-isi: 400 1rem/1.62 "Inter", system-ui, sans-serif;

hitungan: 40/16 = 2.5rem, 48/40 = 1.2; 26/16 = 1.62

/* Dev Mode (mentah) */
.frame-12 { position: absolute; width: 343px; height: 56px; left: 16px; top: 612px;
            background: #0F766E; border-radius: 12px; font-family: 'Plus Jakarta Sans'; font-size: 16px; }

/* Ditulis ulang: mengalir dan responsif */
.btn-primary {
  display: inline-flex; align-items: center; justify-content: center;
  width: 100%; min-height: 56px; padding-inline: 24px;
  background: #0F766E; color: #FFFFFF;
  border-radius: 12px; font: 600 16px/1.2 'Plus Jakarta Sans', system-ui, sans-serif;
}
